<section class="mg-app-shell mg-admin-app"><?php require dirname(__DIR__).'/includes/admin-sidebar.php'; ?><div class="mg-app-workspace mg-admin-workspace"><main class="mg-admin-blog-shell"><header class="mg-admin-blog-hero is-editor"><div><a class="mg-admin-blog-back" href="/admin/blog-posts.php">← Blog manager</a><span class="mg-eyebrow">Content Studio</span><h1>Blog settings</h1><p>Control public blog defaults, launch messaging, RSS, sitemap, and default CTA behavior.</p></div><div class="mg-admin-blog-actions"><a class="mg-btn mg-btn-soft" href="/blog.php" target="_blank" rel="noopener">View blog</a><a class="mg-btn mg-btn-ghost" href="/admin/blog-media.php">Media</a></div></header><?php if(!$ready): ?><section class="mg-admin-blog-alert"><strong>SQL migration required.</strong><span>Run <code>database/microgifter_blog_module.sql</code> before saving settings.</span></section><?php endif; ?><?php if($notice!==''): ?><section class="mg-admin-blog-alert is-success"><strong>Saved.</strong><span><?= mg_e($notice) ?></span></section><?php endif; ?><?php if($error!==''): ?><section class="mg-admin-blog-alert is-error"><strong>Action failed.</strong><span><?= mg_e($error) ?></span></section><?php endif; ?><form class="mg-admin-blog-settings-grid" method="post" action="/admin/blog-settings.php"><?= mg_csrf_field() ?><section class="mg-admin-blog-panel mg-admin-blog-settings-panel"><h2>Public identity</h2><label>Blog title<input type="text" name="blog_title" maxlength="180" value="<?= mg_e($settings['blog_title']) ?>"></label><label>Meta description<textarea name="blog_description" rows="4" maxlength="255"><?= mg_e($settings['blog_description']) ?></textarea></label><label>Default social image<input type="text" name="default_social_image" value="<?= mg_e($settings['default_social_image']) ?>" placeholder="/uploads/blog/media/social.jpg"></label></section><section class="mg-admin-blog-panel mg-admin-blog-settings-panel"><h2>Publishing defaults</h2><label>Posts per page<in